#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static unsigned char static_data[32768];

struct lexer {
    const char *start, *pos, *end;
};

static int next(struct lexer *lexer)
{
    if (lexer->pos >= lexer->end) {
        lexer->pos = lexer->end + 1;
        return '\0';
    }
    int r = *lexer->pos;
    lexer->pos++;
    return r;
}

static void ignore(struct lexer *lexer) { lexer->start = lexer->pos; }
static void advance_n(struct lexer *lexer, size_t n) { lexer->pos += n; ignore(lexer); }
static int peek(struct lexer *lexer) { int c = next(lexer); lexer->pos--; return c; }

int main(void) {
    size_t size = 32768;
    memcpy(static_data, "'''", 3);
    memset(static_data+3, 'a', size-3);

    struct lexer lexer = {
        .start = (char*)static_data,
        .pos = (char*)static_data,
        .end = (char*)static_data + size - 1,
    };

    // simulate lex_config detecting '''
    // pos at 0, read first '
    next(&lexer); // pos=1
    // check strncmp(pos, "''", 2)
    if (strncmp(lexer.pos, "''", 2) == 0) {
        printf("multiline detected\n");
    }
    // peek
    int p = peek(&lexer);
    printf("peek=%c\n", p);
    char *end = (p == '"') ? "\"\"\"" : "'''";
    advance_n(&lexer, strlen("'''") - 1);
    printf("pos offset after advance: %ld\n", (long)(lexer.pos - (char*)static_data));

    int iter = 0;
    do {
        if (!strncmp(lexer.pos, end, 3)) {
            printf("found end at iter %d, pos=%ld\n", iter, (long)(lexer.pos - (char*)static_data));
            break;
        }
        iter++;
    } while (next(&lexer) != '\0');
    printf("loop done, iter=%d, final pos=%ld\n", iter, (long)(lexer.pos - (char*)static_data));
    return 0;
}
